examples.template:
MonarchAiInlineDiff(
    segments,
    onAccept: { id in segments = MonarchAiInlineDiff.resolve(segments, change: id, decision: .accept) },
    onReject: { id in segments = MonarchAiInlineDiff.resolve(segments, change: id, decision: .reject) }
)

examples.setupTemplate:
@State private var segments = MonarchAiDiffSegment.words(
    from: {{before}},
    to: {{after}}
)

examples.setup:
@State private var segments = MonarchAiDiffSegment.words(
    from: "Our team meets every week to review the plan. We will ship the new flow in May, and collect feedback after.",
    to: "Our team meets every Monday to review the roadmap. We will ship the redesigned flow in June, and collect feedback after launch."
)

examples.code:
